class Base:
    def __init__(self, nombre):
        self.nombre = nombre

    def saludar(self):
        return f"Hola, {self.nombre}"

class Derivada(Base):
    def __init__(self, nombre, turno):
        super().__init__(nombre)      # primero la parte heredada
        self.turno = turno

    def saludar(self):                # sobrescribe el método
        base = super().saludar()      # reutiliza lo que ya existía
        return f"{base} (turno {self.turno})"

d = Derivada("Ana", "mañana")
print(d.saludar())
print(isinstance(d, Base))

