#include <iostream>
#include <string>
#include <utility>

class Animal {
public:
    explicit Animal(std::string nombre) : nombre_(std::move(nombre)) {}
    virtual ~Animal() = default;
    virtual std::string hablar() const { return "..."; }
    std::string nombre() const { return nombre_; }

private:
    std::string nombre_;
};

class Perro : public Animal {
public:
    explicit Perro(std::string nombre) : Animal(std::move(nombre)) {}
    std::string hablar() const override { return "Guau"; }
};

int main() {
    Perro p{"Toby"};
    std::cout << p.hablar() << '\n';
    std::cout << p.nombre() << '\n';
    return 0;
}

