from abc import ABC, abstractmethod

class Transformador(ABC):
    @abstractmethod
    def ajustar(self, datos):
        ...

    @abstractmethod
    def transformar(self, datos):
        ...

class EscaladorMinMax(Transformador):
    def __init__(self):
        self.minimo = None
        self.maximo = None

    def ajustar(self, datos):
        self.minimo = min(datos)
        self.maximo = max(datos)

    def transformar(self, datos):
        rango = self.maximo - self.minimo
        return [round((x - self.minimo) / rango, 2) for x in datos]

class Centrador(Transformador):
    def __init__(self):
        self.media = 0

    def ajustar(self, datos):
        self.media = sum(datos) / len(datos)

    def transformar(self, datos):
        return [round(x - self.media, 2) for x in datos]

datos = [10, 20, 30]
for transformador in (EscaladorMinMax(), Centrador()):
