import math
from abc import ABC, abstractmethod

class Figura(ABC):
    @abstractmethod
    def area(self):
        ...

    def describir(self):
        return f"{type(self).__name__}: área {self.area():.2f}"

class Rectangulo(Figura):
    def __init__(self, base, altura):
        self.base = base
        self.altura = altura

    def area(self):
        return self.base * self.altura

class Circulo(Figura):
    def __init__(self, radio):
        self.radio = radio

    def area(self):
        return math.pi * self.radio ** 2

for figura in [Rectangulo(3, 4), Circulo(2)]:
    print(figura.describir())

try:
    Figura()
except TypeError as error:
    print("TypeError:", error)

class Empleado:
    def __init__(self, nombre, base):
        self.nombre = nombre
        self.base = base

    def sueldo(self):
        return self.base

    def __str__(self):
        return f"{self.nombre}: {self.sueldo():.2f}"

class Vendedor(Empleado):
    def __init__(self, nombre, base, ventas):
        super().__init__(nombre, base)
        self.ventas = ventas

    def sueldo(self):
        return super().sueldo() + self.ventas * 0.1

class Gerente(Empleado):
    def __init__(self, nombre, base, bono):
        super().__init__(nombre, base)
        self.bono = bono

    def sueldo(self):
        return super().sueldo() + self.bono

planilla = [Empleado("Ana", 1500), Vendedor("Luis", 1200, 5000), Gerente("Eva", 3000, 800)]
for empleado in planilla:
    print(empleado)
print("Total:", sum(e.sueldo() for e in planilla))

